function notConfigured() {
  return {
    status: 501,
    body: {
      ok: false,
      error: 'MEDIA_RETRIEVAL_NOT_CONFIGURED',
      available: false,
      message: 'Media retrieval is not configured yet.'
    }
  }
}

const providers = {
  none: async () => notConfigured()
}

export function createMediaResolver(providerName = 'none') {
  const provider = providers[providerName] || providers.none

  return async (input) => provider(input)
}

export const resolveMedia = createMediaResolver()
